const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';

/**
 * Reads SQL migration files from the migrations directory
 * and logs each filename it would apply, in order.
 */
function runMigrations() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log(`Migration directory "${MIGRATIONS_DIR}" does not exist.`);
    return;
  }

  // Read all files from the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for SQL files and sort them in numerical/alphabetical order
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort();

  if (sqlFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${sqlFiles.length} migration file(s). Applying in order:\n`);

  // Log each filename that would be applied
  sqlFiles.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    const sql = fs.readFileSync(filePath, 'utf8');

    console.log(`${index + 1}. ${filename}`);
    console.log(`   File size: ${sql.length} bytes\n`);
  });

  console.log(`\nTotal migrations to apply: ${sqlFiles.length}`);
}

// Run the migration script
runMigrations();

