const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.
 */
function migrate() {
  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.log('No migrations directory found.');
    return;
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(migrationsDir);

  // Filter for SQL files only
  const sqlFiles = files.filter(file => file.endsWith('.sql'));

  // Sort files in order (assumes files are named with a prefix like 001_, 002_, etc.)
  sqlFiles.sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }));

  // Check if there are any SQL files to apply
  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  // Log each filename that would be applied
  console.log('Migration files to apply:');
  console.log('--------------------------');
  sqlFiles.forEach((filename, index) => {
    console.log(`${index + 1}. ${filename}`);
  });
  console.log('--------------------------');
  console.log(`Total: ${sqlFiles.length} migration(s)`);
}

// Run the migration
migrate();

