const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');
const envFilePath = path.join(__dirname, '.env.test');

/**
 * Read DATABASE_URL from .env.test file
 */
function getDatabaseUrl() {
  if (!fs.existsSync(envFilePath)) {
    return null;
  }

  const envContent = fs.readFileSync(envFilePath, 'utf8');
  const match = envContent.match(/^DATABASE_URL=(.+)$/m);

  return match ? match[1] : null;
}

/**
 * Resolve connection string from DATABASE_URL
 */
function resolveConnectionString() {
  const databaseUrl = getDatabaseUrl();

  if (!databaseUrl) {
    console.log('DATABASE_URL not found in .env.test');
    return null;
  }

  // Parse the connection string (format: postgres://user:pass@host:port/dbname)
  const urlMatch = databaseUrl.match(/^(\w+):\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/);

  if (urlMatch) {
    const [, protocol, user, , host, port, database] = urlMatch;
    return {
      protocol,
      user,
      host,
      port: parseInt(port, 10),
      database
    };
  }

  return { raw: databaseUrl };
}

